"""Generate crawlable service/case pages from verified portfolio content."""
from pathlib import Path
from html import escape as e
import json,re
R=Path(__file__).resolve().parents[1];BASE='https://devabraao.com.br';WA='https://wa.me/5547992101675';cases=json.loads((R/'data/cases.json').read_text())
services=[
 ('sites','Criação de sites para empresas','Um site precisa explicar o seu negócio e facilitar o próximo passo.','Apresentação confusa, informações difíceis de encontrar e caminhos longos até o contato podem atrapalhar a experiência do cliente.','Organizo conteúdo, navegação e ações a partir do que a empresa precisa comunicar. O escopo pode incluir uma apresentação institucional, catálogo ou cardápio digital.',['Entender o público e o objetivo da página','Definir conteúdo, navegação e contato','Desenvolver o layout para celular e computador','Validar os caminhos que o visitante precisa percorrer']),
 ('sistemas','Desenvolvimento de sistemas sob medida','Clientes, pedidos e informações dentro de um fluxo que faça sentido.','Quando os dados ficam dispersos, acompanhar a operação exige procurar informações em vários lugares. Antes de desenvolver, é preciso entender quem usa, quais etapas existem e como elas se conectam.','Desenvolvo sistemas web com telas e fluxos definidos pelo problema. Gestão de clientes, cobranças, pedidos e acompanhamento são exemplos presentes nos projetos do portfólio.',['Mapear a rotina e as informações necessárias','Definir permissões, telas e integrações do escopo','Construir e validar os fluxos com quem usa','Entregar e combinar os próximos passos de evolução']),
 ('automacoes','Automações e integrações para negócios','Conectar ferramentas para reduzir etapas repetidas na operação.','Copiar informações entre ferramentas e repetir ações manuais consome atenção. A primeira etapa é identificar o que pode ser conectado e quais decisões precisam continuar sob controle humano.','Planejo automações e integrações a partir do fluxo existente. APIs e inteligência artificial podem apoiar atendimento e organização da informação quando fizerem sentido para o problema.',['Identificar tarefas e regras do processo','Conferir as ferramentas e APIs disponíveis','Definir validações, exceções e acompanhamento','Testar o fluxo antes de colocar a solução em uso'])]
slugs={'day':'day-lanches','smart':'smart-billingg','anarosa':'anarosa','nexa':'nexa-store'}
links=[(f'/servicos/{slug}.html',title) for slug,title,*_ in services]+[(f'/projetos/{slugs[c["id"]]}.html',c['name']) for c in cases]
style='''@font-face{font-family:Manrope;src:url(/fonts/manrope-regular.ttf);font-display:swap}*{box-sizing:border-box}body{margin:0;background:#f4f0e8;color:#171714;font-family:Manrope,Arial,sans-serif;line-height:1.8}a{color:inherit;text-underline-offset:5px}a:focus-visible{outline:2px solid #ae4a00;outline-offset:5px}header,main,footer{max-width:1100px;margin:auto;padding:30px 6vw}header{display:flex;justify-content:space-between;border-bottom:1px solid #d8cfc0;gap:20px}.brand{font-size:23px;font-weight:800;text-decoration:none;letter-spacing:-1px}.brand span{color:#d65c08}nav{display:flex;gap:24px;align-items:center;font-size:12px}.crumb{font-size:12px;color:#6b6256;margin:30px 0 45px}.tag{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:#8a430d}h1{font-size:clamp(36px,5.7vw,65px);line-height:1.08;letter-spacing:-2.2px;font-weight:600;max-width:900px;margin:20px 0 30px}.intro{font-size:clamp(18px,2vw,25px);max-width:750px;color:#60584d}section{border-top:1px solid #d8cfc0;padding:35px 0;margin-top:35px}h2{font-size:27px;letter-spacing:-.8px;line-height:1.3}p,li{max-width:760px;font-size:15px}li{margin:12px 0}figure{margin:40px 0}img{max-width:100%;height:auto;border-radius:12px}figcaption{font-size:11px;color:#6b6256}.cta{display:inline-block;background:#171714;color:#fff7ed;padding:14px 24px;border-radius:28px;text-decoration:none;margin:15px 10px 15px 0;font-size:13px}.flow{display:flex;flex-wrap:wrap;gap:10px;padding:0;list-style:none}.flow li{border:1px solid #d8cfc0;padding:7px 13px;border-radius:25px;font-size:12px}footer{border-top:1px solid #d8cfc0;margin-top:40px;font-size:12px}.related{display:flex;flex-wrap:wrap;gap:15px 25px}.skip{position:absolute;top:-80px;left:10px;background:white;padding:10px}.skip:focus{top:0}@media(max-width:600px){header,main,footer{padding:24px}nav{gap:16px}.brand{font-size:21px}.crumb{margin-block:25px 35px}h1{letter-spacing:-1.3px}h2{font-size:24px}}'''
def page(path,title,description,h1,tag,body,image=None,kind='WebPage'):
 url=BASE+path;crumb='Serviços' if path.startswith('/servicos') else 'Projetos';img=BASE+'/'+(image or 'img/foto-hero.jpg');title=title+' | dev.abraao'
 schema={'@context':'https://schema.org','@graph':[{'@type':'WebPage','@id':url+'#page','url':url,'name':h1,'description':description,'inLanguage':'pt-BR','isPartOf':{'@id':BASE+'/#website'},'about':{'@id':BASE+'/#person'}},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Início','item':BASE+'/'},{'@type':'ListItem','position':2,'name':h1,'item':url}]}]}
 if kind=='Service':schema['@graph'].append({'@type':'Service','name':h1,'description':description,'url':url,'provider':{'@type':'Person','@id':BASE+'/#person','name':'Abraão Lima Ribeiro'}})
 content=f'''<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(description)}"><meta name="robots" content="index,follow"><link rel="canonical" href="{url}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR"><meta property="og:site_name" content="dev.abraao"><meta property="og:url" content="{url}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:image" content="{img}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(description)}"><meta name="twitter:image" content="{img}"><style>{style}</style><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')}</script></head><body><a class="skip" href="#conteudo">Ir para o conteúdo</a><header><a class="brand" href="/">dev<span>.abraao</span></a><nav aria-label="Navegação principal"><a href="/#projetos">Projetos</a><a href="/#contato">Contato</a></nav></header><main id="conteudo"><nav class="crumb" aria-label="Caminho da página"><a href="/">Início</a><span aria-hidden="true">/</span><span>{crumb}</span></nav><p class="tag">{e(tag)}</p><h1>{e(h1)}</h1>{body}<section><h2>O que precisa funcionar melhor no seu negócio?</h2><p>Conte o contexto, o que já existe e onde a rotina está travando. A conversa começa pelo problema; as ferramentas são definidas depois.</p><a class="cta" href="{WA}" target="_blank" rel="noopener noreferrer">Conversar no WhatsApp ↗</a><a href="/#contato">Conhecer o assistente de projetos</a></section><section><h2>Outras soluções e projetos</h2><div class="related">{''.join(f'<a href="{p}">{e(t)}</a>' for p,t in links if p!=path)}</div></section></main><footer>Abraão Lima Ribeiro · Desenvolvedor de soluções digitais.<br><a href="/">Voltar à experiência principal</a></footer></body></html>'''
 out=R/path.lstrip('/');out.parent.mkdir(exist_ok=True);out.write_text(content)
for slug,title,intro,problem,solution,steps in services:
 body=f'<p class="intro">{e(intro)}</p><section><h2>Qual problema essa solução pode resolver?</h2><p>{e(problem)}</p></section><section><h2>Como a solução é definida</h2><p>{e(solution)}</p><ol>'+''.join(f'<li>{e(s)}</li>'for s in steps)+'</ol></section><section><h2>Escopo, prazo e investimento</h2><p>O projeto é definido depois de entender as funcionalidades, o conteúdo e as integrações necessárias. Prazo e investimento dependem desse escopo e são apresentados em uma proposta.</p></section>'
 page(f'/servicos/{slug}.html',title,intro,title,'Soluções digitais',body,kind='Service')
for c in cases:
 body=f'<p class="intro">{e(c["phases"][0]["body"])}</p><figure><img src="/{c["screen"]}" alt="{e(c["note"])}" width="1200" height="824"><figcaption>{e(c["note"])}</figcaption></figure>'
 for ph in c['phases'][:3]:body+=f'<section><h2>{e(ph["label"].capitalize())}: {e(re.sub("<br>"," ",ph["title"]).capitalize())}</h2><p>{e(ph["body"])}</p></section>'
 body+='<section><h2>O fluxo da experiência</h2><ul class="flow">'+''.join(f'<li>{e(f)}</li>'for f in c['flow'])+'</ul><p>'+e(c['phases'][3]['body'])+'</p>'
 if c['url']:body+=f'<a class="cta" href="{e(c["url"])}" target="_blank" rel="noopener noreferrer">Explorar o projeto ↗</a>'
 if c['id']=='nexa':body+='<p>Este case usa o nome Nexa Store da apresentação do portfólio. O endereço externo preserva a experiência Nexa Story do acervo.</p>'
 body+='</section>'
 page(f'/projetos/{slugs[c["id"]]}.html',c['name']+' — '+c['category'].lower(),c['phases'][2]['body'],c['name']+' — '+c['category'].lower(),'Case · problema, raciocínio e solução',body,c['screen'])
(R/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{BASE}{p}</loc></url>\n'for p in ['/']+[p for p,t in links])+'</urlset>\n')
print('SEO: 3 serviços, 4 cases e sitemap com 8 URLs.')
